                dict(label='Qué la completaría', points=[dict(text='Los protocolos notariales, los libros de diezmos y los padrones de impuestos, y los relatos de la época sobre el campo castellano; sin ellos no cabe generalizar.', quotes=[Q('es_poblacion','Las cifras anteriores al siglo XVII son altamente especulativas'), Q('es_felipe2','La vida de los españoles del tiempo era dura')])]),
